import HeroSectionV9 from "./hero-section-v9"

export default function Page() {
  return (
    <div className="p-6">
      <HeroSectionV9 />
    </div>
  )
}

import HeroContent from "./hero-content"

import type { HeroV9Props } from "./config"

import "./hero-section-v9.css"

export default function HeroSectionV9(props: HeroV9Props) {
  return (
    <section className="pt-10 pb-16 md:pt-14 md:pb-20 lg:pt-16 lg:pb-24">
      <div className="mx-auto max-w-6xl px-4">
        <HeroContent {...props} />
      </div>
    </section>
  )
}

import CtaButtons from "./cta-buttons"
import ProductPreviewShell from "./product-preview-shell"

import type { HeroV9Props } from "./config"
import { resolveHeroV9Content, resolveHeroV9Preview } from "./config"

export default function HeroContent(props: HeroV9Props) {
  const content = resolveHeroV9Content(props)
  const preview = resolveHeroV9Preview(props.preview)

  return (
    <div className="flex flex-col items-center gap-6 text-center">
      <h1 className="max-w-3xl text-3xl font-medium tracking-tight sm:text-4xl lg:text-5xl lg:leading-[1.15]">
        {content.title}
      </h1>

      <p className="max-w-xl text-base leading-relaxed text-muted-foreground sm:text-lg">
        {content.description}
      </p>

      <CtaButtons
        primaryCta={content.primaryCta}
        secondaryCta={content.secondaryCta}
      />

      <div className="w-full pt-2">
        <ProductPreviewShell preview={preview} />
      </div>
    </div>
  )
}

"use client"

import ActivityPanel from "./activity-panel"
import MetricsRow from "./metrics-row"
import TasksPanel from "./tasks-panel"
import { useLiveDashboardPreview } from "./use-live-dashboard-preview"

import type { ProductPreviewConfig } from "./config"

export default function ProductPreviewShell({
  preview,
}: {
  preview: ProductPreviewConfig
}) {
  const live = useLiveDashboardPreview(preview)

  return (
    <div
      className="pp-root relative mx-auto w-full max-w-5xl overflow-hidden rounded-xl bg-(--pp-shell-bg) shadow-(--pp-shadow)"
      role="img"
      aria-label="Operations dashboard preview"
    >
      <MetricsRow metrics={live.metrics} pulseKey={live.pulseKey} />
      <div className="hero-v9-panels grid grid-cols-1 items-stretch lg:grid-cols-2">
        <ActivityPanel activity={live.panels.activity} live />
        <TasksPanel tasks={live.panels.tasks} />
      </div>
    </div>
  )
}

import MetricCard from "./metric-card"

export default function MetricsRow({
  metrics,
  pulseKey,
}: {
  metrics: ReadonlyArray<{ value: string; label: string }>
  pulseKey?: number
}) {
  return (
    <div className="hero-v9-metrics relative z-1">
      {metrics.map((metric) => (
        <MetricCard
          key={metric.label}
          value={metric.value}
          label={metric.label}
          pulseKey={pulseKey}
        />
      ))}
    </div>
  )
}

import { cn } from "@/lib/utils"

export default function MetricCard({
  value,
  label,
  pulseKey,
}: {
  value: string
  label: string
  pulseKey?: number
}) {
  return (
    <div className="hero-v9-metric flex flex-col items-center justify-center gap-1 px-3 py-4 text-center">
      <span
        key={`${value}-${pulseKey ?? 0}`}
        className={cn(
          "hero-v9-metric-value text-2xl font-medium tracking-tight text-foreground tabular-nums",
          pulseKey !== undefined && pulseKey > 0 && "hero-v9-metric-live"
        )}
      >
        {value}
      </span>
      <span className="font-mono text-[0.6875rem] uppercase tracking-wider text-muted-foreground">
        {label}
      </span>
    </div>
  )
}

import { cn } from "@/lib/utils"

import type { ProductPreviewConfig } from "./config"

type ActivityConfig = ProductPreviewConfig["panels"]["activity"]

export default function ActivityPanel({
  activity,
  live = false,
}: {
  activity: ActivityConfig
  live?: boolean
}) {
  const maxIndex = activity.bars.reduce(
    (best, height, index) => (height > activity.bars[best] ? index : best),
    0
  )

  return (
    <div className="hero-v9-activity-panel relative z-1 flex min-h-0 flex-1 flex-col">
      <h3 className="hero-v9-panel-heading flex shrink-0 items-center justify-between gap-2 px-4 py-2.5 text-sm font-medium text-foreground">
        <span>{activity.title}</span>
        {live ? (
          <span
            className="hero-v9-live-signal"
            aria-hidden
            title="Simulated live data"
          >
            <span className="hero-v9-live-signal-bar" />
            <span className="hero-v9-live-signal-bar" />
            <span className="hero-v9-live-signal-bar" />
          </span>
        ) : null}
      </h3>

      <div
        className={cn(
          "hero-v9-activity-chart flex min-h-0 w-full flex-1 items-end justify-between gap-1 px-4 py-3",
          live && "hero-v9-activity-chart-live"
        )}
        aria-hidden
      >
        {activity.bars.map((height, index) => (
          <div
            key={index}
            className={cn(
              "hero-v9-bar w-2 shrink-0 rounded-t-sm",
              live && "hero-v9-bar-live",
              index === maxIndex
                ? "bg-(--pp-accent)"
                : "bg-(--pp-accent-muted)"
            )}
            style={{
              height: `${height}%`,
              animationDelay: live ? `${Math.min(index * 14, 560)}ms` : undefined,
            }}
          />
        ))}
      </div>
    </div>
  )
}

import StatusChip from "./status-chip"

import type { ProductPreviewConfig } from "./config"

type TasksConfig = ProductPreviewConfig["panels"]["tasks"]

export default function TasksPanel({ tasks }: { tasks: TasksConfig }) {
  return (
    <div className="relative z-1 flex min-h-0 flex-col">
      <h3 className="hero-v9-panel-heading shrink-0 px-4 py-2.5 text-sm font-medium text-foreground">
        {tasks.legendTitle}
      </h3>

      <div className="flex flex-wrap gap-x-4 gap-y-2 px-4 py-3">
        {tasks.legend.map((item) => (
          <StatusChip key={item.label} label={item.label} state={item.state} />
        ))}
      </div>

      <h4 className="hero-v9-section-heading px-4 py-2 font-mono text-xs text-muted-foreground">
        {tasks.tableTitle}
      </h4>

      <div className="font-mono text-xs">
        <div className="hero-v9-table-head grid grid-cols-3 items-center justify-items-center px-4 py-2 text-center text-muted-foreground">
          <span>Automation</span>
          <span>Status</span>
          <span>Last run</span>
        </div>

        {tasks.rows.map((row) => (
          <div
            key={row.automation}
            className="hero-v9-table-row hero-v9-table-row-live grid grid-cols-3 items-center justify-items-center px-4 py-2.5 text-center"
          >
            <span className="text-sm text-foreground/80">{row.automation}</span>
            <StatusChip label={row.status} state={row.state} />
            <span className="text-xs text-muted-foreground tabular-nums">
              {row.lastRun}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"

import type { PreviewStatusState } from "./config"

export default function StatusChip({
  label,
  state,
}: {
  label: string
  state: PreviewStatusState
}) {
  return (
    <div className="inline-flex items-center gap-1.5">
      <span
        className={cn(
          "relative size-1.5 shrink-0 rounded-full",
          state === "waiting" ? "bg-(--pp-dot-idle)" : "bg-(--pp-accent)",
          state === "running" && "hero-v9-status-live"
        )}
        aria-hidden
      />
      <span
        className={cn(
          "text-sm transition-colors duration-500",
          state === "waiting" ? "text-muted-foreground" : "text-foreground/80",
          state === "running" && "text-foreground"
        )}
      >
        {label}
      </span>
    </div>
  )
}

"use client"

import { useEffect, useRef, useState, useSyncExternalStore } from "react"

import type { PreviewStatusState, ProductPreviewConfig } from "./config"

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

type MetricKind = "k" | "percent" | "minutes" | "integer"

type MetricSeed = {
  label: string
  kind: MetricKind
  value: number
}

type TaskSeed = {
  automation: string
  status: string
  state: PreviewStatusState
  minutesAgo: number
}

export type LiveDashboardPreview = {
  metrics: ReadonlyArray<{ value: string; label: string }>
  panels: ProductPreviewConfig["panels"] & {
    tasks: ProductPreviewConfig["panels"]["tasks"] & {
      rows: ReadonlyArray<{
        automation: string
        status: string
        lastRun: string
        state: PreviewStatusState
      }>
    }
  }
  pulseKey: number
}

const TICK_MS = 2400

function detectMetricKind(value: string): MetricKind {
  if (value.includes("%")) return "percent"
  if (/min/i.test(value)) return "minutes"
  if (/k/i.test(value)) return "k"
  return "integer"
}

function parseMetricValue(value: string, kind: MetricKind): number {
  const numeric = Number.parseFloat(value.replace(/[^\d.]/g, ""))
  if (kind === "k") return numeric * 1000
  return numeric
}

function formatMetricValue(value: number, kind: MetricKind): string {
  switch (kind) {
    case "k":
      return `${(value / 1000).toFixed(1)}K`
    case "percent":
      return `${value.toFixed(1)}%`
    case "minutes":
      return `${value.toFixed(1)} Min`
    default:
      return `${Math.round(value)}`
  }
}

function formatLastRun(minutesAgo: number): string {
  if (minutesAgo <= 0) return "just now"
  if (minutesAgo === 1) return "1 min ago"
  return `${minutesAgo} min ago`
}

function seedMetrics(
  metrics: ProductPreviewConfig["metrics"]
): MetricSeed[] {
  return metrics.map((metric) => {
    const kind = detectMetricKind(metric.value)
    return {
      label: metric.label,
      kind,
      value: parseMetricValue(metric.value, kind),
    }
  })
}

function seedTasks(
  rows: ProductPreviewConfig["panels"]["tasks"]["rows"]
): TaskSeed[] {
  return rows.map((row) => ({
    automation: row.automation,
    status: row.status,
    state: row.state,
    minutesAgo: Number.parseInt(row.lastRun, 10) || 1,
  }))
}

function tickMetrics(metrics: MetricSeed[]): MetricSeed[] {
  return metrics.map((metric) => {
    let next = metric.value

    switch (metric.kind) {
      case "k":
        next += 8 + Math.floor(Math.random() * 18)
        break
      case "percent":
        next += Math.random() > 0.65 ? -0.1 : 0.05
        next = Math.min(99.9, Math.max(98.4, next))
        break
      case "minutes":
        next += (Math.random() - 0.5) * 0.12
        next = Math.min(2.2, Math.max(1.1, next))
        break
      default:
        next += Math.floor(Math.random() * 3) - 1
        next = Math.max(24, next)
        break
    }

    return { ...metric, value: next }
  })
}

function tickBars(bars: ReadonlyArray<number>): number[] {
  const next = bars.slice(1)
  next.push(42 + Math.floor(Math.random() * 54))
  return next
}

function tickTasks(tasks: TaskSeed[], cyclePhase: number): TaskSeed[] {
  return tasks.map((task, index) => {
    let { status, state, minutesAgo } = task

    minutesAgo = state === "running" ? minutesAgo : minutesAgo + 1

    if (index === 1) {
      return { ...task, status, state, minutesAgo: Math.max(0, minutesAgo - 1) }
    }

    if (cyclePhase === 0 && index === 2 && state !== "running") {
      status = "Running"
      state = "running"
      minutesAgo = 0
    } else if (cyclePhase === 2 && index === 2 && state === "running") {
      status = "Completed"
      state = "success"
      minutesAgo = 1
    } else if (cyclePhase === 4 && index === 0 && state !== "running") {
      status = "Running"
      state = "running"
      minutesAgo = 0
    } else if (cyclePhase === 6 && index === 0 && state === "running") {
      status = "Completed"
      state = "success"
      minutesAgo = 1
    }

    return { ...task, status, state, minutesAgo }
  })
}

function buildPreview(
  config: ProductPreviewConfig,
  metrics: MetricSeed[],
  bars: number[],
  tasks: TaskSeed[],
  pulseKey: number
): LiveDashboardPreview {
  return {
    metrics: metrics.map((metric) => ({
      label: metric.label,
      value: formatMetricValue(metric.value, metric.kind),
    })),
    panels: {
      activity: {
        title: config.panels.activity.title,
        bars,
      },
      tasks: {
        legendTitle: config.panels.tasks.legendTitle,
        legend: config.panels.tasks.legend,
        tableTitle: config.panels.tasks.tableTitle,
        rows: tasks.map((task) => ({
          automation: task.automation,
          status: task.status,
          state: task.state,
          lastRun: formatLastRun(task.minutesAgo),
        })),
      },
    },
    pulseKey,
  }
}

export function useLiveDashboardPreview(
  config: ProductPreviewConfig
): LiveDashboardPreview {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer
  )

  const metricsRef = useRef(seedMetrics(config.metrics))
  const barsRef = useRef([...config.panels.activity.bars])
  const tasksRef = useRef(seedTasks(config.panels.tasks.rows))
  const cycleRef = useRef(0)

  const [preview, setPreview] = useState<LiveDashboardPreview>(() =>
    buildPreview(
      config,
      seedMetrics(config.metrics),
      [...config.panels.activity.bars],
      seedTasks(config.panels.tasks.rows),
      0
    )
  )

  useEffect(() => {
    if (reducedMotion) {
      setPreview(
        buildPreview(
          config,
          metricsRef.current,
          barsRef.current,
          tasksRef.current,
          0
        )
      )
      return
    }

    const interval = window.setInterval(() => {
      metricsRef.current = tickMetrics(metricsRef.current)
      barsRef.current = tickBars(barsRef.current)
      cycleRef.current = (cycleRef.current + 1) % 8
      tasksRef.current = tickTasks(tasksRef.current, cycleRef.current)

      setPreview((current) =>
        buildPreview(
          config,
          metricsRef.current,
          barsRef.current,
          tasksRef.current,
          current.pulseKey + 1
        )
      )
    }, TICK_MS)

    return () => window.clearInterval(interval)
  }, [config, reducedMotion])

  return preview
}

export type HeroV9Cta = {
  label: string
  href: string
}

export type PreviewStatusState = "success" | "running" | "waiting"

export type HeroV9Content = {
  title: string
  description: string
  primaryCta: HeroV9Cta
  secondaryCta: HeroV9Cta
}

export type ProductPreviewConfig = {
  metrics: ReadonlyArray<{ value: string; label: string }>
  panels: {
    activity: {
      title: string
      bars: ReadonlyArray<number>
    }
    tasks: {
      legendTitle: string
      legend: ReadonlyArray<{ label: string; state: PreviewStatusState }>
      tableTitle: string
      rows: ReadonlyArray<{
        automation: string
        status: string
        lastRun: string
        state: PreviewStatusState
      }>
    }
  }
}

