export type HeroV9Props = Partial<HeroV9Content> & {
  preview?: Partial<ProductPreviewConfig>
}

export function resolveHeroV9Content(overrides?: HeroV9Props): HeroV9Content {
  return {
    title: overrides?.title ?? heroV9Content.title,
    description: overrides?.description ?? heroV9Content.description,
    primaryCta: overrides?.primaryCta ?? heroV9Content.primaryCta,
    secondaryCta: overrides?.secondaryCta ?? heroV9Content.secondaryCta,
  }
}

export function resolveHeroV9Preview(
  overrides?: HeroV9Props["preview"]
): ProductPreviewConfig {
  if (!overrides) return heroV9Preview

  return {
    metrics: overrides.metrics ?? heroV9Preview.metrics,
    panels: {
      activity: {
        ...heroV9Preview.panels.activity,
        ...overrides.panels?.activity,
      },
      tasks: {
        ...heroV9Preview.panels.tasks,
        ...overrides.panels?.tasks,
      },
    },
  }
}

/* hero-section-v9 — product preview tokens (--pp-*) + panel grid borders */

.pp-root {
  --pp-shell-bg: oklch(0.985 0 0);
  --pp-border: rgb(0 0 0 / 0.1);
  --pp-v-border: 1px dashed var(--pp-border);
  --pp-h-border: 1px solid var(--pp-border);
  --pp-accent: rgb(39 39 42);
  --pp-accent-muted: rgb(39 39 42 / 0.28);
  --pp-accent-soft: rgb(39 39 42 / 0.06);
  --pp-accent-ring: rgb(39 39 42 / 0.35);
  --pp-accent-row: rgb(39 39 42 / 0.04);
  --pp-muted: rgb(113 113 122);
  --pp-dot-active: rgb(39 39 42);
  --pp-dot-idle: rgb(161 161 170 / 0.35);
  --pp-radius: 0.75rem;
  --pp-shadow: 0 24px 48px -28px rgb(0 0 0 / 0.12);
  --pp-noise-opacity: 0.03;
  border-top: var(--pp-h-border);
  border-bottom: var(--pp-h-border);
  border-left: var(--pp-v-border);
  border-right: var(--pp-v-border);
}

.dark .pp-root {
  --pp-shell-bg: oklch(0.12 0 0);
  --pp-border: rgb(255 255 255 / 0.1);
  --pp-v-border: 1px dashed var(--pp-border);
  --pp-h-border: 1px solid var(--pp-border);
  --pp-accent: rgb(228 228 231);
  --pp-accent-muted: rgb(228 228 231 / 0.28);
  --pp-accent-soft: rgb(228 228 231 / 0.08);
  --pp-accent-ring: rgb(228 228 231 / 0.35);
  --pp-accent-row: rgb(228 228 231 / 0.06);
  --pp-muted: rgb(150 150 150);
  --pp-dot-active: rgb(242 242 242);
  --pp-dot-idle: rgb(242 242 242 / 0.35);
  --pp-shadow: 0 24px 48px -28px rgb(0 0 0 / 0.45);
  --pp-noise-opacity: 0.05;
}

.pp-root::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: var(--pp-noise-opacity);
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 128px 128px;
}

.hero-v9-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-bottom: var(--pp-h-border);
}

@media (min-width: 640px) {
  .hero-v9-metrics {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.hero-v9-metrics .hero-v9-metric {
  border-right: var(--pp-v-border);
}

.hero-v9-metrics .hero-v9-metric:nth-child(2n) {
  border-right: none;
}

@media (min-width: 640px) {
  .hero-v9-metrics .hero-v9-metric:nth-child(2n) {
    border-right: var(--pp-v-border);
  }

  .hero-v9-metrics .hero-v9-metric:nth-child(4n) {
    border-right: none;
  }
}

.hero-v9-activity-panel {
  border-bottom: var(--pp-h-border);
}

@media (min-width: 1024px) {
  .hero-v9-activity-panel {
    border-bottom: none;
    border-right: var(--pp-v-border);
  }
}

.hero-v9-panel-heading,
.hero-v9-section-heading,
.hero-v9-table-head,
.hero-v9-table-row {
  border-bottom: var(--pp-h-border);
}

.hero-v9-table-row:last-child {
  border-bottom: none;
}

.hero-v9-panels {
  min-height: 14rem;
}

.hero-v9-activity-chart {
  width: 100%;
  height: 100%;
  min-height: 8rem;
}

.hero-v9-activity-chart-live {
  position: relative;
  overflow: hidden;
}

.hero-v9-activity-chart-live::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--pp-accent-soft) 50%,
    transparent 100%
  );
  transform: translateX(-100%);
  animation: hero-v9-chart-scan 5s ease-in-out infinite;
}

.hero-v9-bar {
  transform-origin: bottom;
  transition:
    height 700ms cubic-bezier(0.4, 0, 0.2, 1),
    background-color 500ms ease;
}

.hero-v9-bar-live {
  animation: hero-v9-bar-rise 700ms cubic-bezier(0.4, 0, 0.2, 1) backwards;
}

.hero-v9-live-signal {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 0.625rem;
}

.hero-v9-live-signal-bar {
  width: 2px;
  height: 100%;
  border-radius: 1px;
  background: var(--pp-accent);
  transform-origin: bottom;
  animation: hero-v9-live-signal 1.1s ease-in-out infinite;
}

.hero-v9-live-signal-bar:nth-child(1) {
  animation-delay: 0s;
}

.hero-v9-live-signal-bar:nth-child(2) {
  animation-delay: 0.12s;
}

.hero-v9-live-signal-bar:nth-child(3) {
  animation-delay: 0.24s;
}

.hero-v9-metric-live {
  animation: hero-v9-metric-tick 650ms ease;
}

.hero-v9-status-live {
  animation: hero-v9-status-ring 1.8s ease-out infinite;
}

.hero-v9-table-row-live {
  transition: background-color 450ms ease;
}

.hero-v9-table-row-live:has(.hero-v9-status-live) {
  background: var(--pp-accent-row);
}

@keyframes hero-v9-bar-rise {
  from {
    transform: scaleY(0.15);
    opacity: 0.35;
  }

  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

@keyframes hero-v9-chart-scan {
  0%,
  100% {
    transform: translateX(-100%);
    opacity: 0;
  }

  12% {
    opacity: 1;
  }

  45% {
    transform: translateX(100%);
    opacity: 1;
  }

  55% {
    opacity: 0;
  }
}

@keyframes hero-v9-live-signal {
  0%,
  100% {
    transform: scaleY(0.3);
    opacity: 0.45;
  }

  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

@keyframes hero-v9-metric-tick {
  0% {
    opacity: 0.5;
    transform: translateY(3px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes hero-v9-status-ring {
  0% {
    box-shadow: 0 0 0 0 var(--pp-accent-ring);
  }

  70% {
    box-shadow: 0 0 0 5px transparent;
  }

  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pp-root .animate-pulse {
    animation: none;
  }

  .hero-v9-bar,
  .hero-v9-bar-live,
  .hero-v9-activity-chart-live::after,
  .hero-v9-live-signal-bar,
  .hero-v9-metric-live,
  .hero-v9-status-live,
  .hero-v9-table-row-live {
    animation: none;
    transition: none;
  }
}
